class Solution {
public:
    int count = 0;
    void expand(string& s, int l, int r) {
        while (l >= 0 && r < (int)s.size() && s[l] == s[r]) {
            count++;
            l--;
            r++;
        }
    }
    int countSubstrings(string s) {
        for (int c = 0; c < (int)s.size(); c++) {
            expand(s, c, c);
            expand(s, c, c + 1);
        }
        return count;
    }
};
